"""Per-thread (scalar accumulator) Triton kernels for the per-tetrahedron moments and their vertex VJP; generated by
gen_fast_tet2 (see fast_tet.py for the formulas). One tetrahedron per lane; the 125 moments in 5 passes over the x power
(25 accumulators each), the backward in 5 passes (the vertex gradient is linear in grad p, so passes add up)."""
import torch
import triton
import triton.language as tl
from fast_tet import _geom


@triton.jit
def _fwd2(tets_ptr, tref_ptr, tw_ptr, out_ptr, T, Q: tl.constexpr, BLOCK_T: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK_T + tl.arange(0, BLOCK_T)
    mask = offs < T
    v0x, v0y, v0z, e1x, e1y, e1z, e2x, e2y, e2z, e3x, e3y, e3z = _geom(tets_ptr, offs, mask)
    det = e1x * (e2y * e3z - e2z * e3y) - e1y * (e2x * e3z - e2z * e3x) + e1z * (e2x * e3y - e2y * e3x)
    J = tl.abs(det)
    m00 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m01 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m02 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m03 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m04 = tl.zeros([BLOCK_T], dtype=tl.float64)
