    m21 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m22 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m23 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m24 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m30 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m31 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m32 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m33 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m34 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m40 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m41 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m42 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m43 = tl.zeros([BLOCK_T], dtype=tl.float64)
    m44 = tl.zeros([BLOCK_T], dtype=tl.float64)
    for q in range(Q):
        r1 = tl.load(tref_ptr + 3 * q + 0); r2 = tl.load(tref_ptr + 3 * q + 1); r3 = tl.load(tref_ptr + 3 * q + 2)
        w = tl.load(tw_ptr + q)
        x = v0x + r1 * e1x + r2 * e2x + r3 * e3x
        y = v0y + r1 * e1y + r2 * e2y + r3 * e3y
        z = v0z + r1 * e1z + r2 * e2z + r3 * e3z
        s0 = w
        y2 = y * y; z2 = z * z
        s1 = s0 * y; s2 = s0 * y2; s3 = s1 * y2; s4 = s2 * y2
        z3 = z2 * z; z4 = z2 * z2
        m00 += s0; m01 += s0 * z; m02 += s0 * z2; m03 += s0 * z3; m04 += s0 * z4
        m10 += s1; m11 += s1 * z; m12 += s1 * z2; m13 += s1 * z3; m14 += s1 * z4
        m20 += s2; m21 += s2 * z; m22 += s2 * z2; m23 += s2 * z3; m24 += s2 * z4
        m30 += s3; m31 += s3 * z; m32 += s3 * z2; m33 += s3 * z3; m34 += s3 * z4
        m40 += s4; m41 += s4 * z; m42 += s4 * z2; m43 += s4 * z3; m44 += s4 * z4
